  var choice = selectOption({ title: '穆鲁的挽歌：选择要丢弃的圣光手牌', options: options, selectionMode: 'multi', presentation: 'hand', minSelections: 1, maxSelections: Math.min(4, holyCards.length), canCancel: true });
